from articles.service import serialize_article

def test_serialize_article_author():
    article = {"id": 1, "title": "Hello", "author_id": 10}
    user = {"id": 10}
    result = serialize_article(article, user)
    print(f"Author: {result['can_edit']} (expected True)")
    assert result['can_edit'] is True

def test_serialize_article_non_author():
    article = {"id": 1, "title": "Hello", "author_id": 10}
    user = {"id": 11}
    result = serialize_article(article, user)
    print(f"Non-author: {result['can_edit']} (expected False)")
    assert result['can_edit'] is False

def test_serialize_article_anonymous():
    article = {"id": 1, "title": "Hello", "author_id": 10}
    user = None
    result = serialize_article(article, user)
    print(f"Anonymous: {result['can_edit']} (expected False)")
    assert result['can_edit'] is False

if __name__ == "__main__":
    try:
        test_serialize_article_author()
        test_serialize_article_non_author()
        test_serialize_article_anonymous()
        print("All tests passed!")
    except Exception as e:
        print(f"Caught exception: {e}")
        raise e
